import { Reminder } from "../domain/reminder";
import { LocalDate } from "../time/localTime";

/** 예약해 둔 알림 — 키 단위로 한 번만 저장된다. */
export class ReminderRepository {
  private readonly rows = new Map<string, Reminder>();

  has(key: string): boolean {
    return this.rows.has(key);
  }

  save(r: Reminder): void {
    this.rows.set(r.key, { ...r });
  }

  find(key: string): Reminder | undefined {
    const r = this.rows.get(key);
    return r ? { ...r } : undefined;
  }

  byPlanDate(date: LocalDate): Reminder[] {
    return [...this.rows.values()]
      .filter((r) => r.planDate === date)
      .sort((a, b) => (a.sendAt < b.sendAt ? -1 : a.sendAt > b.sendAt ? 1 : a.key < b.key ? -1 : 1))
      .map((r) => ({ ...r }));
  }

  byAutopay(autopayId: string): Reminder[] {
    return [...this.rows.values()].filter((r) => r.autopayId === autopayId).map((r) => ({ ...r }));
  }

  remove(key: string): void {
    this.rows.delete(key);
  }
}
import { Autopay, BillingFailure } from "../domain/autopay";

export class AutopayRepository {
  private readonly rows = new Map<string, Autopay>();
  private readonly failures: BillingFailure[] = [];
  private seq = 0;

  create(input: Omit<Autopay, "id" | "active">): Autopay {
    this.seq++;
    const a: Autopay = { ...input, id: `AP${String(this.seq).padStart(5, "0")}`, active: true };
    this.rows.set(a.id, a);
    return { ...a };
  }

  find(id: string): Autopay | undefined {
    const a = this.rows.get(id);
    return a ? { ...a } : undefined;
  }

  deactivate(id: string): void {
    const a = this.rows.get(id);
    if (a) a.active = false;
  }

  /** 해당 출금일에 출금되는 활성 계약 — 등록 순 */
  billingOn(day: number): Autopay[] {
    return [...this.rows.values()].filter((a) => a.active && a.billingDay === day).map((a) => ({ ...a }));
  }

  addFailure(f: BillingFailure): void {
    this.failures.push({ ...f });
  }

  failuresOf(autopayId: string): BillingFailure[] {
    return this.failures.filter((f) => f.autopayId === autopayId).map((f) => ({ ...f }));
  }
}
# 출금 실패 통보 수신 (운영 메모)

출금 실패는 펌뱅킹 중계사(뱅크허브)가 출금 시스템(billing-core)과 이 서비스에 각각 통보한다.
이 서비스는 `POST /autopays/:id/failures`로 받는다.

## 통보 형식
| 필드 | 내용 |
|---|---|
| autopayId | 계약 번호 |
| failedAt | 통보 시각(KST, 초 단위) |
| reason | `INSUFFICIENT_BALANCE`·`ACCOUNT_CLOSED`·`LIMIT_EXCEEDED` |

- 통보에는 별도 거래 번호가 없다. 계약 번호와 시각으로만 구분된다.
- 뱅크허브는 수신 응답이 30초 안에 오지 않으면 같은 건을 다시 통보한다(3~6분 간격, 최대 3회). 다시 보낸 통보의 failedAt은 원래 실패 시각이 아니라 다시 보낸 시각이다.
- 08:00 출금 배치 직후처럼 통보가 몰리는 시간대에는 응답 지연으로 재통보가 자주 생긴다.

## 재출금
- billing-core가 실패 통보 기준 2시간 뒤 재출금을 잡는다. 재출금이 또 실패하면 그 시점에서 다시 2시간 뒤.
- billing-core는 재출금이 잡혀 있는 동안 들어온 통보로는 재출금을 새로 잡지 않는다.

## 장애 시
- 뱅크허브 연결이 끊기면 실패 통보가 늦게 몰려 들어온다. 재출금 안내가 재출금 뒤에 도착할 수 있으니 결제운영팀에 공유한다.
- 통보 누락 의심 시 billing-core의 실패 목록과 대조한다(운영 콘솔 > 출금 > 실패).

